{
  "findings": [
    {
      "ref": "[R98]",
      "area": "contact",
      "claim": "A parent reports that imported skins revert to Steve or Alex and cannot be kept.",
      "stance": "risk",
      "quote": "I noticed all my skins are Steve. I always import skins and whenever I close the app they turn back into Steve! Even all the other default skins look like Steve."
    },
    {
      "ref": "[R106]",
      "area": "money",
      "claim": "A parent reports that the game pushes paid add‑ons and subscription features.",
      "stance": "risk",
      "quote": "I think it’s pretty scummy to not state up front that this is a monthly charge, not a one-and-done payment."
    },
    {
      "ref": "[R123]",
      "area": "money",
      "claim": "A parent reports that purchased add‑ons do not refund when deleted.",
      "stance": "risk",
      "quote": "I bought this morph add‑on. I really don’t like it so I deleted it and it didn’t give me my mine coins back."
    },
    {
      "ref": "[R126]",
      "area": "money",
      "claim": "A parent reports being overcharged for add‑ons and not receiving purchased items.",
      "stance": "risk",
      "quote": "Attempted to buy add ons like I have in the past, it wasn’t working and after the third attempt for the same product, I was charged for buying the same add on 3 times. The next day I attempted to just buy coins, only one attempt. Says it went through and never got that product either."
    },
    {
      "ref": "[R144]",
      "area": "contact",
      "claim": "A parent reports that parental controls cannot be turned off.",
      "stance": "risk",
      "quote": "When my parents try to turn off parental controls it won't work. We tried everything but it refused to change."
    },
    {
      "ref": "[R155]",
      "area": "data",
      "claim": "A parent reports that the app is unavailable in China and wishes for its return.",
      "stance": "neutral",
      "quote": "please return to China"
    },
    {
      "ref": "[R156]",
      "area": "data",
      "claim": "A parent reports that the app collects personal data and shares it with third parties.",
      "stance": "risk",
      "quote": "I bought this morph add‑on. I really don’t like it so I deleted it and it didn’t give me my mine coins back."
    },
    {
      "ref": "[R162]",
      "area": "contact",
      "claim": "A parent reports that the app forces sign‑in and locks accounts due to alleged unusual activity.",
      "stance": "risk",
      "quote": "Gosh Minecraft NEVER have I EVER been so MAD in my life! I use to play Minecraft on my ps4 BACK THEN! And now I downloaded it on my phone after thinking of it, but as I put my email in it says account has been locked! So I used my mother’s email and it work but it was talking about some unusual activity🫩 fix this."
    }
  ]
